      const { values, errors } = state;

      return `
        <form id="support-form" novalidate>
          ${FormField({
            id: "fullName",
            label: "Full name",
            type: "text",
            value: values.fullName,
            placeholder: "Jordan Lee",
            required: true,
            error: errors.fullName
          })}
          ${FormField({
            id: "email",
            label: "Email address",
            type: "email",
            value: values.email,
            placeholder: "jordan@example.com",
            required: true,
            error: errors.email
