<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: rgba(19, 28, 52, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e5eefb;
      --muted: #9fb0cc;
      --accent: #7dd3fc;
      --accent-strong: #38bdf8;
      --input: rgba(15, 23, 42, 0.92);
      --input-border: rgba(125, 211, 252, 0.22);
      --error: #fda4af;
      --success: #86efac;
      --shadow: 0 28px 60px rgba(2, 8, 23, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.16), transparent 28%),
        linear-gradient(180deg, #060816 0%, #0b1020 55%, #080c18 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .page-shell {
      width: min(100%, 720px);
    }

    .support-card {
      background: var(--panel);
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      padding: 32px;
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.76rem;
      font-weight: 700;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 2.75rem);
      line-height: 1.1;
    }

    .intro {
      margin: 14px 0 0;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      margin-top: 28px;
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-size: 0.95rem;
      font-weight: 600;
    }

    .required-mark {
      color: var(--accent);
    }

    input {
      width: 100%;
      border: 1px solid var(--input-border);
      background: var(--input);
      color: var(--text);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      transition: border-color 140ms ease, box-shadow 140ms ease, transform 140ms ease;
    }

    input::placeholder {
      color: #6f84a8;
    }

    input:focus {
      outline: none;
      border-color: var(--accent-strong);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.18);
      transform: translateY(-1px);
    }

    .field-hint,
    .field-error,
    .form-status {
      font-size: 0.88rem;
      line-height: 1.5;
    }

    .field-hint {
      color: var(--muted);
    }

    .field-error {
      color: var(--error);
    }

    .form-status {
      color: var(--success);
      margin: 0;
    }

    button {
      margin-top: 6px;
      border: 0;
      border-radius: 999px;
      padding: 14px 20px;
      background: linear-gradient(135deg, var(--accent-strong), #2563eb);
      color: #03111f;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: transform 140ms ease, box-shadow 140ms ease, filter 140ms ease;
      box-shadow: 0 18px 30px rgba(37, 99, 235, 0.28);
    }

    button:hover {
      filter: brightness(1.06);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(125, 211, 252, 0.45);
      outline-offset: 3px;
    }

    @media (max-width: 640px) {
      .support-card {
        padding: 24px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      errors: {},
      submitted: false,
      successMessage: ""
    };

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function validate(values) {
      const errors = {};

      if (!values.fullName.trim()) {
        errors.fullName = "Enter your full name.";
      }

      if (!values.email.trim()) {
        errors.email = "Enter your email address.";
      } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) {
        errors.email = "Enter a valid email address.";
      }

      return errors;
    }

    function FormField({ id, label, type, value, placeholder, required, hint, error }) {
      const describedBy = [hint ? id + "-hint" : "", error ? id + "-error" : ""]
        .filter(Boolean)
        .join(" ");

      return `
        <div class="form-field">
          <label for="${id}">
            ${label}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ""}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            value="${escapeHtml(value)}"
            placeholder="${escapeHtml(placeholder)}"
            ${required ? "required" : ""}
            aria-required="${required ? "true" : "false"}"
            ${error ? 'aria-invalid="true"' : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
          />
          ${hint ? `<div class="field-hint" id="${id}-hint">${hint}</div>` : ""}
          ${error ? `<div class="field-error" id="${id}-error">${error}</div>` : ""}
        </div>
      `;
    }

    function ContactForm() {
      const { values, errors } = state;

      return `
        <form id="support-form" novalidate>
          ${FormField({
            id: "fullName",
            label: "Full name",
            type: "text",
            value: values.fullName,
            placeholder: "Jordan Lee",
            required: true,
            error: errors.fullName
          })}
          ${FormField({
            id: "email",
            label: "Email address",
            type: "email",
            value: values.email,
            placeholder: "jordan@example.com",
            required: true,
            error: errors.email
          })}
          ${FormField({
            id: "phone",
            label: "Phone number",
            type: "tel",
            value: values.phone,
            placeholder: "(555) 123-4567",
            required: false,
            hint: "Optional. Use a format such as (555) 123-4567 or +1 555 123 4567.",
            error: errors.phone
          })}
          ${state.successMessage ? `<p class="form-status" role="status">${state.successMessage}</p>` : ""}
          <button type="submit">Submit request</button>
        </form>
      `;
    }

    function SupportPage() {
      return `
        <main class="page-shell">
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">Contact our support team</h1>
            <p class="intro">
              Share your details and we will follow up with the right next step for your request.
            </p>
            ${ContactForm()}
          </section>
        </main>
      `;
    }

    function render() {
      document.getElementById("app").innerHTML = SupportPage();

      const form = document.getElementById("support-form");
      form.addEventListener("input", handleInput);
      form.addEventListener("submit", handleSubmit);
    }

    function handleInput(event) {
      const { name, value } = event.target;
      state.values[name] = value;
      state.successMessage = "";

      if (state.submitted) {
        state.errors = validate(state.values);
        render();
      }
    }

    function handleSubmit(event) {
      event.preventDefault();
      state.submitted = true;
      state.errors = validate(state.values);

      if (Object.keys(state.errors).length > 0) {
        render();
        const firstInvalidField = document.querySelector("[aria-invalid='true']");
        if (firstInvalidField) {
          firstInvalidField.focus();
        }
        return;
      }

      state.values = {
        fullName: "",
        email: "",
        phone: ""
      };
      state.errors = {};
      state.submitted = false;
      state.successMessage = "Your support request has been submitted.";
      render();
    }

    render();
  </script>
</body>
</html>
